{"content": "1|/* Twinthos redesign — global.css
2|   Black bg, white text, #20F782 signal only.
3|   Inter only. No cards/pills/badges. Hairline borders.
4|   Left-aligned asymmetry. One idea per viewport. */
5|
6|:root{
7|  --bg:#000000;
8|  --bg-2:#0a0a0a;
9|  --hair:#1a1a1a;
10|  --hair-soft:#111;
11|  --ink:#ffffff;
12|  --lt:#b0b0b0;
13|  --dk:#666;
14|  --signal:#20F782;
15|  --signal-dim:#15805a;
16|  --sans:'Inter',system-ui,-apple-system,sans-serif;
17|  --mono:'IBM Plex Mono',ui-monospace,monospace;
18|  --wrap:1100px;
19|  --gut:52px;
20|  --ease:cubic-bezier(.22,1,.36,1);
21|  --nav-h:56px;
22|}
23|
24|@media(max-width:900px){:root{--gut:32px}}
25|@media(max-width:600px){:root{--gut:20px}}
26|
27|*{margin:0;padding:0;box-sizing:border-box}
28|html{scroll-behavior:smooth;scroll-padding-top:var(--nav-h)}
29|body{background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:18px;line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:hidden}
30|@media(max-width:600px){body{font-size:17px}}
31|
32|a{color:inherit;text-decoration:none}
33|a:hover{color:var(--signal)}
34|
35|img,svg{display:block}
36|
37|.wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--gut)}
38|
39|/* Skip link */
40|.skip{position:absolute;left:-9999px;background:var(--ink);color:var(--bg);padding:10px 16px;font-size:14px;font-weight:600;z-index:1000;border:1px solid var(--ink)}
41|.skip:focus{left:12px;top:12px;outline:none}
42|
43|/* Focus */
44|:focus-visible{outline:2px solid var(--signal);outline-offset:3px}
45|
46|/* Selection */
47|::selection{background:var(--signal);color:var(--bg)}
48|
49|/* Type */
50|h1,h2,h3{font-family:var(--sans);font-weight:300;letter-spacing:-.025em;line-height:1.1}
51|h1{font-size:clamp(48px,7vw,96px);font-weight:300;letter-spacing:-.035em;line-height:1.02}
52|h2{font-size:clamp(32px,4.5vw,52px);font-weight:300;letter-spacing:-.025em;margin-bottom:20px}
53|h3{font-size:clamp(20px,2vw,26px);font-weight:400;letter-spacing:-.01em}
54|p{max-width:68ch}
55|.eyebrow{font-family:var(--mono);font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:var(--signal);margin-bottom:28px}
56|.sub{font-size:19px;color:var(--lt);max-width:60ch;line-height:1.65}
57|.support{font-size:15px;color:var(--dk);max-width:60ch}
58|.label{font-family:var(--mono);font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--dk)}
59|.mono{font-family:var(--mono)}
60|
61|/* Hairline */
62|hr.sep{border:none;border-top:1px solid var(--hair);margin:0}
63|.rule{border-top:1px solid var(--hair)}
64|
65|/* Nav */
66|.nav{position:fixed;top:0;left:0;right:0;height:var(--nav-h);z-index:100;background:var(--bg);border-bottom:1px solid var(--hair);display:flex;align-items:center}
67|.nav-in{display:flex;align-items:center;gap:32px;height:100%;padding:0 var(--gut);max-width:var(--wrap);margin:0 auto}
68|.nav-brand{display:flex;align-items:center;gap:10px;font-size:14px;letter-spacing:.18em;font-weight:500;color:var(--ink)}
69|.nav-brand svg{width:22px;height:22px}
70|.nav-links{display:flex;gap:36px;font-size:15px;color:var(--lt)}
71|.nav-links a{transition:color .15s}
72|.nav-links a:hover{color:var(--ink)}
73|.nav-cta{margin-left:auto}
74|.nav-cta a{font-size:14px;letter-spacing:.04em;font-weight:500;padding:10px 22px;border:1px solid var(--signal);color:var(--signal);transition:background .15s,color .15s}
75|.nav-cta a:hover{background:var(--signal);color:var(--bg)}
76|.nav-burger{display:none;background:none;border:1px solid var(--hair);color:var(--ink);font-size:20px;width:40px;height:40px;cursor:pointer;align-self:flex-end;margin-left:auto}
77|
78|@media(max-width:900px){
79|  .nav-cta{margin-left:auto}
80|  .nav-links{display:none;position:absolute;top:var(--nav-h);left:0;right:0;background:var(--bg);border-top:1px solid var(--hair);flex-direction:column;gap:0;padding:8px var(--gut)}
81|  .nav-links.open{display:flex}
82|  .nav-links a{padding:18px 0;font-size:17px;border-bottom:1px solid var(--hair);color:var(--ink)}
83|  .nav-links a:hover{color:var(--signal)}
84|  .nav-burger{display:block}
85|}
86|
87|/* Buttons */
88|.btn{display:inline-flex;align-items:center;font-family:var(--sans);font-size:15px;font-weight:500;letter-spacing:.02em;padding:13px 28px;min-height:48px;border:1px solid transparent;cursor:pointer;transition:transform .15s var(--ease),background .15s,color .15s,border-color .15s}
89|.btn-primary{background:var(--signal);color:var(--bg);border-color:var(--signal)}
90|.btn-primary:hover{background:var(--signal-dim);border-color:var(--signal-dim);transform:translateY(-1px)}
91|.btn-ghost{background:transparent;color:var(--ink);border-color:var(--hair)}
92|.btn-ghost:hover{border-color:var(--lt);color:var(--lt)}
93|.btn-text{background:none;color:var(--lt);padding:8px 0;min-height:0;font-size:15px}
94|.btn-text:hover{color:var(--ink)}
95|.btn-sm{padding:9px 18px;font-size:14px;min-height:38px}
96|
97|.cta-row{display:flex;flex-wrap:wrap;gap:16px;margin-top:40px}
98|.cta-row.center{justify-content:center}
99|
100|/* Page hero */
101|.page-hero{padding:var(--nav-h) 0 0}
102|.page-hero .wrap{padding-top:calc(var(--nav-h) + 48px)}
103|
104|/* Sections */
105|section{padding:clamp(72px,9vw,110px) 0;position:relative}
106|section + section{border-top:1px solid var(--hair)}
107|
108|.sec-head{margin-bottom:clamp(40px,5vw,64px)}
109|.sec-head .eyebrow{margin-bottom:20px}
110|
111|/* Hero */
112|.hero{padding:clamp(100px,14vh,180px) 0 clamp(40px,5vw,60px);border-bottom:1px solid var(--hair)}
113|.hero-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(40px,6vw,80px);align-items:start;position:relative}
114|@media(max-width:900px){.hero-grid{grid-template-columns:1fr;gap:48px}}
115|
116|.hero h1{margin-bottom:24px}
117|.hero .sub{margin-top:28px;margin-bottom:36px}
118|
119|.hero-meta{position:absolute;bottom:0;left:0;right:0;height:1px;background:var(--hair)}
120|@media(max-width:900px){.hero-meta{display:none}}
121|
122|/* Proof line */
123|.proof-line{font-family:var(--mono);font-size:13px;letter-spacing:.1em;text-transform:uppercase;color:var(--signal);margin-bottom:32px;display:flex;align-items:center;gap:10px}
124|.proof-line::before{content:"";width:6px;height:6px;background:var(--signal);border-radius:50%}
125|
126|/* Record / evidence block */
127|.record-block{border-top:1px solid var(--hair)}
128|.record-head{display:flex;justify-content:space-between;align-items:center;padding:20px 0;border-bottom:1px solid var(--hair);margin-bottom:24px}
129|.record-head .mono{font-size:13px;color:var(--dk)}
130|.record-title{font-size:22px;font-weight:400;margin-bottom:20px}
131|.record-lines{display:grid;gap:14px}
132|.record-line{display:grid;grid-template-columns:28px 1fr;gap:14px;align-items:start;padding:12px 0;border-top:1px solid var(--hair)}
133|.record-line:first-child{border-top:none;padding-top:0}
134|.record-line .tick{font-size:16px;color:var(--signal);margin-top:2px}
135|.record-line p{font-size:17px;color:var(--lt)}
136|.record-foot{margin-top:24px;padding-top:18px;border-top:1px solid var(--hair);font-size:14px;color:var(--dk)}
137|
138|/* Steps */
139|.steps-display{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1px solid var(--hair)}
140|@media(max-width:900px){.steps-display{grid-template-columns:1fr}}
141|.step-item{padding:28px 28px 28px 0;border-right:1px solid var(--hair);border-top:1px solid var(--hair)}
142|.step-item:first-child{border-left:none;padding-left:0}
143|.step-item:last-child{border-right:none;padding-right:0}
144|@media(max-width:900px){
145|  .step-item{border-right:none;border-bottom:1px solid var(--hair);padding:24px 0;padding-right:0;border-left:none}
146|  .step-item:last-child{border-bottom:none}
147|}
148|.step-num{font-family:var(--mono);font-size:12px;color:var(--signal);letter-spacing:.1em;text-transform:uppercase;margin-bottom:16px}
149|.step-item h3{margin-bottom:10px}
150|.step-item p{font-size:16px;color:var(--lt)}
151|
152|/* Workflow list */
153|.wf-list{border-top:1px solid var(--hair)}
154|.wf-item{display:grid;grid-template-columns:1fr 1fr;gap:0;border-top:1px solid var(--hair)}
155|@media(max-width:900px){.wf-item{grid-template-columns:1fr}}
156|.wf-item:first-child{border-top:none}
157|.wf-item .wf-label{padding:28px 28px 28px 0;border-right:1px solid var(--hair);border-top:1px solid var(--hair)}
158|@media(max-width:900px){.wf-item .wf-label{border-right:none;border-top:1px solid var(--hair);padding:20px 0}}
159|.wf-item .wf-label:first-child{border-left:none;padding-left:0}
160|.wf-item .wf-label:last-child{border-right:none;padding-right:0}
161|.wf-label .step-num{margin-bottom:14px}
162|.wf-label h3{margin-bottom:10px;font-size:20px}
163|.wf-label p{font-size:16px;color:var(--lt)}
164|.wf-item .wf-body{padding:28px;border-top:1px solid var(--hair);border-right:none}
165|@media(max-width:900px){.wf-item .wf-body{border-top:1px solid var(--hair)}}
166|.wf-body p{font-size:17px;color:var(--lt)}
167|
168|/* FAQ */
169|.faq-list{border-top:1px solid var(--hair)}
170|.faq-item{border-bottom:1px solid var(--hair)}
171|.faq-item summary{display:flex;justify-content:space-between;align-items:baseline;gap:20px;cursor:pointer;padding:24px 0;font-size:18px;font-weight:400;color:var(--ink);list-style:none;transition:color .15s}
172|.faq-item summary:hover{color:var(--signal)}
173|.faq-item summary::-webkit-details-marker{display:none}
174|.faq-item summary::before{content:"+";font-family:var(--mono);font-size:20px;color:var(--signal);flex-shrink:0;transition:transform .2s var(--ease)}
175|.faq-item[open] summary::before{content:"−";transform:rotate(0)}
176|.faq-item .faq-answer{max-height:0;overflow:hidden;transition:max-height .25s var(--ease)}
177|.faq-item[open] .faq-answer{max-height:300px}
178|.faq-item p{padding:0 0 24px 0;color:var(--lt);font-size:17px}
179|
180|/* Pricing / offer */
181|.price-block{border-top:1px solid var(--hair);padding-top:0}
182|.price-figure{display:grid;grid-template-columns:1fr auto;gap:40px;align-items:end;padding:48px 0;border-bottom:1px solid var(--hair)}
183|.price-figure .price{font-size:clamp(56px,8vw,100px);font-weight:300;letter-spacing:-.04em;line-height:1;font-variant-numeric:tabular-nums}
184|.price-figure .price .currency{font-size:24px;vertical-align:super;color:var(--signal);font-weight:400}
185|.price-figure .per{font-size:18px;color:var(--lt);margin-top:12px;max-width:28ch}
186|.price-figure .price-spacer{visibility:hidden}
187|
188|.price-details{display:grid;gap:0;border-top:1px solid var(--hair)}
189|.price-detail{padding:24px 0;border-top:1px solid var(--hair)}
190|.price-detail p{font-size:17px;color:var(--lt)}
191|
192|/* Form */
193|.form-block{border-top:1px solid var(--hair)}
194|.form-row{display:grid;gap:0;border-top:1px solid var(--hair)}
195|.form-field{padding:24px 0;border-top:1px solid var(--hair)}
196|.form-field label{display:block;font-family:var(--mono);font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--dk);margin-bottom:12px}
197|.form-field input,.form-field textarea,.form-field select{width:100%;background:transparent;color:var(--ink);border:none;outline:none;font-family:var(--sans);font-size:17px;padding:0;margin-bottom:18px;border-top:1px solid var(--hair)}
198|.form-field textarea{min-height:100px;resize:vertical;font-family:var(--sans)}
199|.form-field input::placeholder,.form-field textarea::placeholder{color:var(--dk)}
200|.form-field input:focus,.form-field textarea:focus{border-top-color:var(--signal)}
201|.form-note{font-size:14px;color:var(--dk);margin-top:8px}
202|
203|.form-submit{display:flex;align-items:center;gap:16px;margin-top:24px;padding-top:24px;border-top:1px solid var(--hair)}
204|.form-submit .btn{flex:1}
205|
206|/* Form confirmation */
207|.form-confirmation{display:grid;gap:20px;padding:48px 0;border-top:1px solid var(--hair)}
208|.form-confirmation .check{font-size:32px;color:var(--signal);margin-bottom:8px}
209|.form-confirmation h2{margin-bottom:12px}
210|.form-confirmation p{color:var(--lt);font-size:17px}
211|
212|/* Footer */
213|.foot{padding:clamp(48px,6vw,64px) 0 32px;border-top:1px solid var(--hair)}
214|.foot-in{display:grid;grid-template-columns:1.4fr 1fr;gap:48px;padding-bottom:32px;border-bottom:1px solid var(--hair)}
215|@media(max-width:900px){.foot-in{grid-template-columns:1fr;gap:32px}}
216|.foot-brand{display:flex;align-items:center;gap:10px;font-size:14px;letter-spacing:.18em;margin-bottom:16px}
217|.foot-brand svg{width:20px;height:20px}
218|.foot-brand .brand-name{font-size:14px;letter-spacing:.18em}
219|.foot-brand p{color:var(--dk);font-size:15px;margin-top:12px;max-width:36ch}
220|.foot-col h4{font-family:var(--mono);font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--dk);margin-bottom:16px;font-weight:400}
221|.foot-col ul{list-style:none;display:grid;gap:10px}
222|.foot-col a{color:var(--lt);font-size:15px;transition:color .15s}
223|.foot-col a:hover{color:var(--ink)}
224|.foot-bottom{grid-template-columns:1.4fr 1fr;gap:48px;padding-top:24px}
225|@media(max-width:900px){.foot-bottom{grid-template-columns:1fr}}
226|.foot-bottom p{font-size:14px;color:var(--dk)}
227|.foot-bottom a{color:var(--dk);font-size:14px;margin-left:16px}
228|.foot-bottom a:hover{color:var(--lt)}
229|
230|/* Social proof strip */
231|.social-strip{border-top:1px solid var(--hair);padding:32px 0;display:flex;gap:0;border-bottom:1px solid var(--hair)}
232|.social-strip .item{flex:1;padding:0 20px;border-right:1px solid var(--hair);display:flex;flex-direction:column;gap:8px;min-width:0}
233|.social-strip .item:first-child{border-left:none;padding-left:0}
234|.social-strip .item:last-child{border-right:none;padding-right:0}
235|@media(max-width:600px){.social-strip{flex-wrap:wrap}.social-strip .item{flex:1 1 40%;border-right:none;border-bottom:1px solid var(--hair);padding:16px 0}.social-strip .item:nth-child(3n){border-right:none}}
236|.social-strip .label{font-family:var(--mono);font-size:11px;color:var(--dk);letter-spacing:.1em;text-transform:uppercase}
237|.social-strip .count{font-size:22px;font-weight:300;letter-spacing:-.02em}
238|
239|/* Divider label */
240|.divider-label{display:flex;align-items:center;gap:16px;margin:48px 0}
241|.divider-label::before,.divider-label::after{content:"";flex:1;height:1px;background:var(--hair)}
242|.divider-label span{font-family:var(--mono);font-size:12px;color:var(--dk);letter-spacing:.12em;text-transform:uppercase;white-space:nowrap}
243|
244|/* Privacy specific */
245|.privacy-section{border-top:1px solid var(--hair)}
246|.privacy-item{padding:28px 0;border-top:1px solid var(--hair)}
247|.privacy-item:first-child{border-top:none;padding-top:0}
248|.privacy-item h3{margin-bottom:12px;font-size:20px}
249|.privacy-item p{color:var(--lt);font-size:17px}
250|.privacy-item .label{margin-bottom:10px;display:block}
251|
252|/* TOC for long pages */
253|.toc{display:flex;flex-wrap:wrap;gap:8px 24px;padding:32px 0;border-top:1px solid var(--hair);border-bottom:1px solid var(--hair)}
254|.toc a{font-size:15px;color:var(--lt);transition:color .15s}
255|.toc a:hover{color:var(--ink)}
256|
257|/* Responsive */
258|@media(max-width:600px){
259|  h1{font-size:44px;letter-spacing:-.025em}
260|  h2{font-size:28px}
261|  .nav-in{padding:0 20px;gap:16px}
262|  .nav-links{gap:0}
263|  section{padding:56px 0}
