{"content": "1|/* Twinthos redesign — site.js
2|   Scroll reveals, nav toggle, booking form (fetch, no Formspree), demo controls. */
3|
4|;(function(){
5|  'use strict';
6|
7|  var prefersReduced = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
8|
9|  /* ── Nav burger ── */
10|  var burger = document.getElementById('navBurger');
11|  var navLinks = document.getElementById('navLinks');
12|  if (burger && navLinks) {
13|    burger.addEventListener('click', function(){
14|      var open = navLinks.classList.toggle('open');
15|      burger.setAttribute('aria-expanded', open ? 'true' : 'false');
16|    });
17|    // Close on link click (mobile)
18|    navLinks.querySelectorAll('a').forEach(function(link){
19|      link.addEventListener('click', function(){
20|        navLinks.classList.remove('open');
21|        burger.setAttribute('aria-expanded', 'false');
22|      });
23|    });
24|    // Close on outside click
25|    document.addEventListener('click', function(e){
26|      if (!navLinks.contains(e.target) && !burger.contains(e.target)) {
27|        navLinks.classList.remove('open');
28|        burger.setAttribute('aria-expanded', 'false');
29|      }
30|    });
31|  }
32|
33|  /* ── Scroll reveals (IntersectionObserver) ── */
34|  if (!prefersReduced) {
35|    var reveals = document.querySelectorAll('.reveal');
36|    if (reveals.length) {
37|      var io = new IntersectionObserver(function(entries){
38|        entries.forEach(function(entry){
39|          if (entry.isIntersecting) {
40|            entry.target.classList.add('in');
41|            io.unobserve(entry.target);
42|          }
43|        });
44|      }, {threshold: 0.12, rootMargin: '0px 0px -30px 0px'});
45|      reveals.forEach(function(el){
46|        io.observe(el);
47|      });
48|    }
49|    // Add the CSS for the transition
50|    var style = document.createElement('style');
51|    style.textContent = '.reveal{opacity:0;transform:translateY(12px);transition:opacity .6s cubic-bezier(.22,1,.36,1),transform .6s cubic-bezier(.22,1,.36,1)}.reveal.in{opacity:1;transform:none}';
52|    document.head.appendChild(style);
53|  } else {
54|    document.querySelectorAll('.reveal').forEach(function(el){
55|      el.classList.add('in');
56|    });
57|  }
58|
59|  /* ── Hero fade-in on load ── */
60|  var hero = document.querySelector('.hero');
61|  if (hero && !prefersReduced) {
62|    hero.style.opacity = '0';
63|    hero.style.transform = 'translateY(8px)';
64|    hero.style.transition = 'opacity .8s cubic-bezier(.22,1,.36,1), transform .8s cubic-bezier(.22,1,.36,1)';
65|    window.addEventListener('load', function(){
66|      requestAnimationFrame(function(){
67|        hero.style.opacity = '1';
68|        hero.style.transform = 'none';
69|      });
70|    });
71|  }
72|
73|  /* ── Smooth scroll for same-page anchors (no JS polyfill needed, CSS handles it) ── */
74|
75|  /* ── Booking form (fetch) ── */
76|  var bookingForm = document.getElementById('bookingForm');
77|  if (bookingForm) {
78|    bookingForm.addEventListener('submit', function(e){
79|      e.preventDefault();
80|      var submitBtn = bookingForm.querySelector('.btn-primary[type="submit"]');
81|      var originalText = submitBtn ? submitBtn.textContent : 'Send request';
82|      if (submitBtn) {
83|        submitBtn.disabled = true;
84|        submitBtn.textContent = 'Sending…';
85|      }
86|
87|      var data = new FormData(bookingForm);
88|      var payload = {};
89|      data.forEach(function(val, key){
90|        payload[key] = val;
91|      });
92|
93|      fetch('/api/booking', {
94|        method: 'POST',
95|        headers: {'Content-Type': 'application/json'},
96|        body: JSON.stringify(payload)
97|      })
98|      .then(function(res){
99|        if (!res.ok) throw new Error('Server error');
100|        return res.json();
101|      })
102|      .then(function(){
103|        // Hide form, show confirmation
104|        var formBlock = bookingForm.closest('.form-block');
105|        if (formBlock) {
106|          formBlock.innerHTML =
107|            '<div class="form-confirmation">' +
108|              '<div class="check">&#10003;</div>' +
109|              '<h2>Request received</h2>' +
